class StageParent {
    String pick(Object value){ return "parent-object"; }
    String pick(String value){ return "parent-string"; }
}
class StageChild extends StageParent {
    @Override String pick(Object value){ return "child-object"; }
}
public class OverloadOverrideStagesDemo {
    public static void main(String[] args){
        StageParent ref = new StageChild();
        Object value = "text";
        System.out.println(ref.pick(value));
    }
}
